 if(textCreating_)box=textTransformStart_;
 else{
  if(!selectedTextBoxLayer(currentDocument(),currentDocument().layer().id))return;
  const auto r=currentDocument().timeline().resolveSurface(currentDocument().cel().id);if(!r.source||!r.source->text||!r.source->text->boxed)return;
  const auto& d=*r.source->text;box={double(d.originX.value_or(0)),double(d.originY.value_or(0)),double(d.boxWidth),double(d.boxHeight)};
 }
