  const auto border=uiPhysical(uiLogical(gfx::Rect(cv.x+copy.x*cv.w+int(box.x*canvasScale()),cv.y+copy.y*cv.h+int(box.y*canvasScale()),std::max(1,int(box.width*canvasScale())),std::max(1,int(box.height*canvasScale())))));
  skin_.drawSelectionBorder(g,border,false);
